{"content": "#!/usr/bin/env python3
"""API 中转站 — 多 Provider OpenAI 兼容网关"""

import json, os, time, re
from datetime import datetime
import requests
from flask import Flask, request, jsonify, Response, stream_with_context

app = Flask(__name__)

# ── 加载配置 ─────────────────────────────────────────
with open(os.path.join(os.path.dirname(__file__), "config.json")) as f:
    CONFIG = json.load(f)

SERVER = CONFIG["server"]
AUTH = CONFIG["auth"]
LOCAL_TOKEN = AUTH["local_token"]

# 从环境变量读取 API Keys
API_KEYS = {}
for provider, env_name in CONFIG.get("api_keys", {}).items():
    val = os.environ.get(env_name, "")
    if val:
        API_KEYS[provider] = val

DASHSCOPE_BASE = "https://dashscope.aliyuncs.com/compatible-mode/v1"
SENSENOVA_BASE = "https://token.sensenova.cn/v1"

# ── 统计 ─────────────────────────────────────────────
stats = {"total_requests": 0, "total_tokens": 0, "errors": 0}
start_time = datetime.now()


def get_model_config(model_id: str) -> dict | None:
    """查找模型配置，未匹配时尝试百炼通配回退"""
    # 先精确匹配
    for m in CONFIG["models"]:
        if m["id"] == model_id and m.get("enabled", True):
            return dict(m)

    # 百炼通配：检查 qwen/* 条目是否存在且启用
    for m in CONFIG["models"]:
        if m["id"] == "qwen/*" and m.get("enabled", True):
            if "DASHSCOPE_API_KEY" in os.environ:
                return {
                    "id": model_id,
                    "provider": "dashscope",
                    "base_url": DASHSCOPE_BASE,
                    "model": model_id,
                    "enabled": True,
                    "_passthrough": True,
                }

    return None


def get_upstream_key(provider: str) -> str | None:
    """获取上游 API Key"""
    return API_KEYS.get(provider)


def call_upstream(model_config: dict, payload: dict):
    """调用上游 API 并返回响应"""
    provider = model_config["provider"]
    base_url = model_config["base_url"].rstrip("/")
    model_name = model_config["model"]
    api_key = get_upstream_key(provider)

    if not api_key:
        return {"error": f"未配置 {provider} 的 API Key"}, 500

    headers = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json",
    }

    # 构建请求体
    body = {k: v for k, v in payload.items() if k != "model"}
    body["model"] = model_name

    # SenseNova 特殊处理
    if provider == "sensenova" and "deepseek" in model_name.lower():
        body.setdefault("thinking", {"type": "disabled"})

    url = f"{base_url}/chat/completions"
    stream = payload.get("stream", False)

    try:
        resp = requests.post(
            url, headers=headers, json=body, stream=stream, timeout=300
        )
    except requests.RequestException as e:
        stats["errors"] += 1
        return {"error": f"上游请求失败: {str(e)}"}, 502

    if stream:
        return resp, stream

    data = resp.json()

    # SenseNova Flash-Lite: reasoning → content 映射
    if provider == "sensenova":
        for choice in data.get("choices", []):
            msg = choice.get("message", {})
            if not msg.get("content") and msg.get("reasoning"):
                msg["content"] = msg.pop("reasoning")

    # 统计 tokens
    usage = data.get("usage", {})
    stats["total_tokens"] += usage.get("total_tokens", 0)

    if resp.status_code >= 400:
        stats["errors"] += 1
        return data, resp.status_code

    return data, resp.status_code


# ── 认证中间件 ───────────────────────────────────────

@app.before_request
def check_auth():
    if request.path == "/health":
        return None
    if AUTH.get("require_auth", True):
        token = request.headers.get("Authorization", "").replace("Bearer ", "")
        if token != LOCAL_TOKEN:
            return jsonify({"error": "Unauthorized"}), 401


# ── CORS ─────────────────────────────────────────────

@app.after_request
def add_cors(response):
    response.headers["Access-Control-Allow-Origin"] = "*"
    response.headers["Access-Control-Allow-Headers"] = "*"
    response.headers["Access-Control-Allow-Methods"] = "*"
    return response


# ── 路由 ─────────────────────────────────────────────

@app.route("/health")
def health():
    uptime = str(datetime.now() - start_time).split(".")[0]
    return jsonify({"status": "ok", "uptime": uptime, "stats": stats})


@app.route("/v1/models", methods=["GET"])
def list_models():
    data = [
        {
            "id": m["id"],
            "object": "model",
            "owned_by": m["provider"],
        }
        for m in CONFIG["models"]
        if m.get("enabled", True) and m["id"] != "qwen/*"
    ]
    # 加通配标签
    for m in CONFIG["models"]:
        if m["id"] == "qwen/*" and m.get("enabled", True):
            data.append(
                {
                    "id": "qwen/*",
                    "object": "model",
                    "owned_by": "dashscope",
                    "_wildcard": True,
                    "_count": "166+ models",
                }
            )
    return jsonify({"object": "list", "data": data})


@app.route("/v1/models/dashscope", methods=["GET"])
def list_dashscope_models():
    """列出百炼聊天模型（已过滤 TTS/ASR 等）"""
    api_key = os.environ.get("DASHSCOPE_API_KEY")
    if not api_key:
        return jsonify({"error": "DASHSCOPE_API_KEY not set"}), 500

    try:
        resp = requests.get(
            f"{DASHSCOPE_BASE}/models",
            headers={"Authorization": f"Bearer {api_key}"},
            timeout=30,
        )
        all_models = resp.json().get("data", [])
    except Exception as e:
        return jsonify({"error": f"获取百炼模型列表失败: {str(e)}"}), 502

    # 过滤非聊天模型
    exclude = [
        "tts", "asr", "speech", "realtime", "image", "wan",
        "livetranslate", "mt-", "ocr", "omni", "gui", "audio",
        "vc-", "vd-", "s2s", "xiaomi", "vanchin",
    ]
    chat_models = [
        m
        for m in all_models
        if not any(k in m["id"].lower() for k in exclude)
    ]

    # 分类
    def categorize(mid: str) -> str:
        mid_l = mid.lower()
        if "qwen3.7" in mid_l or "qwen3.6" in mid_l:
            return "🆕 最新旗舰"
        if "qwen3.5" in mid_l:
            return "⭐ Qwen3.5"
        if any(k in mid_l for k in ("qwq", "qvq", "deep-research")):
            return "🤔 深度推理"
        if "coder" in mid_l:
            return "💻 代码编程"
        if "math" in mid_l:
            return "📐 数学推理"
        if "qwen3" in mid_l:
            return "🧠 Qwen3"
        if "deepseek" in mid_l:
            return "🔍 DeepSeek"
        if "kimi" in mid_l:
            return "🌙 Kimi"
        if "glm" in mid_l or "zhipu" in mid_l:
            return "🔥 智谱GLM"
        if "minimax" in mid_l or "abab" in mid_l:
            return "🎭 MiniMax"
        if any(k in mid_l for k in ("qwen1", "qwen2-", "qwen-")):
            return "📦 经典系列"
        return "📦 其他"

    result = [
        {"id": m["id"], "_cat": categorize(m["id"])} for m in chat_models
    ]
    return jsonify(result)


@app.route("/v1/chat/completions", methods=["POST"])
def chat_completions():
    body = request.get_json(force=True)
    model_id = body.get("model", "")

    model_config = get_model_config(model_id)
    if not model_config:
        stats["errors"] += 1
        return jsonify({"error": f"模型 {model_id} 未配置或未启用"}), 404

    stats["total_requests"] += 1

    stream = body.get("stream", False)
    result, status = call_upstream(model_config, body)

    if status != 200:
        return jsonify(result), status

    if stream:
        def generate():
            for chunk in result.iter_content(chunk_size=None):
                if chunk:
                    yield chunk
        return Response(
            stream_with_context(generate()),
            content_type="text/event-stream",
        )

    return jsonify(result), status


@app.route("/stats")
def get_stats():
    """Dashboard 用统计"""
    config_models = [
        {
            "id": m["id"],
            "name": m.get("name", m["id"]),
            "enabled": m.get("enabled", True),
            "_wildcard": m["id"] == "qwen/*",
        }
        for m in CONFIG["models"]
    ]
    return jsonify(
        {
            "uptime": str(datetime.now() - start_time).split(".")[0],
            "stats": stats,
            "models": config_models,
            "providers": list(API_KEYS.keys()),
        }
    )


# ── 启动 ─────────────────────────────────────────────
if __name__ == "__main__":
    print(f"🚀 API 中转站启动: {SERVER['host']}:{SERVER['port']}")
    print(f"   Providers: {', '.join(API_KEYS.keys())}")
    app.run(
        host=SERVER["host"],
        port=SERVER["port"],
        debug=SERVER.get("debug", False),
    )
", "path": "/home/admin/api-relay/server.py"}

