<style>
:root {
  --bg: #0f172a; --card: #1e293b; --text: #e2e8f0;
  --muted: #94a3b8; --accent: #38bdf8; --green: #4ade80;
  --red: #f87171; --yellow: #fbbf24; --border: #334155;
  --blue: #60a5fa;
}
* { margin: 0; padding: 0; box-sizing: border-box; }
body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  background: var(--bg); color: var(--text); min-height: 100vh;
  padding: 16px;
}
.container { max-width: 900px; margin: 0 auto; }
h1 { font-size: 1.4rem; margin-bottom: 4px; }
.subtitle { color: var(--muted); font-size: 0.8rem; margin-bottom: 16px; }

.card {
  background: var(--card); border: 1px solid var(--border);
  border-radius: 10px; padding: 16px; margin-bottom: 12px;
}
.card h2 { font-size: 1rem; margin-bottom: 10px; border-bottom: 1px solid var(--border); padding-bottom: 6px; }

.row { display: flex; gap: 10px; flex-wrap: wrap; margin-bottom: 8px; }
.metric {
  background: rgba(56,189,248,0.08); border: 1px solid var(--border);
  border-radius: 8px; padding: 10px 14px; flex: 1; min-width: 100px; text-align: center;
}
.metric .val { font-size: 1.5rem; font-weight: 700; color: var(--accent); }
.metric .lbl { font-size: 0.7rem; color: var(--muted); margin-top: 2px; }

.status-dot {
  display: inline-block; width: 8px; height: 8px; border-radius: 50%; margin-right: 4px;
}
.status-dot.on { background: var(--green); }
.status-dot.off { background: var(--red); }

.model-row {
  display: flex; align-items: center; justify-content: space-between;
  padding: 8px 0; border-bottom: 1px solid rgba(51,65,85,0.5);
  font-size: 0.85rem;
}
.model-row:last-child { border-bottom: none; }
.toggle {
  padding: 3px 10px; border-radius: 12px; border: none; cursor: pointer;
  font-size: 0.7rem; font-weight: 600; color: #fff;
}
.toggle.on { background: var(--green); }
.toggle.off { background: var(--red); }

select, input, textarea, button {
  background: var(--bg); color: var(--text); border: 1px solid var(--border);
  border-radius: 6px; padding: 8px 10px; font-size: 0.85rem; outline: none;
}
select:focus, input:focus, textarea:focus { border-color: var(--accent); }
