</head>
<body>
<div class="container">
  <h1>🚀 API 中转站</h1>
  <p class="subtitle">OpenAI 兼容接口 · <span id="uptime">--</span></p>

  <!-- 概览 -->
  <div class="card">
    <h2>📊 概览</h2>
    <div class="row" id="metrics">
      <div class="metric"><div class="val" id="m_req">0</div><div class="lbl">请求数</div></div>
      <div class="metric"><div class="val" id="m_tok">0</div><div class="lbl">Tokens</div></div>
      <div class="metric"><div class="val" id="m_err">0</div><div class="lbl">错误</div></div>
      <div class="metric"><div class="val" id="m_pro">0</div><div class="lbl">Provider</div></div>
    </div>
    <p class="providers" id="providers_list"></p>
  </div>

  <!-- 模型列表 -->
  <div class="card">
    <h2>📋 模型列表</h2>
    <div id="model_list">加载中...</div>
  </div>

  <!-- 聊天测试 -->
  <div class="card">
    <h2>💬 聊天测试</h2>
    <div class="row">
      <select id="chatModel" onchange="onModelChange()" style="flex:2">
        <option value="">选择模型...</option>
      </select>
      <button onclick="sendChat()" id="sendBtn" style="flex:0">发送</button>
    </div>
    <div id="wildcardSub" style="display:none; margin:8px 0;">
      <select id="dashscopeModel" style="width:100%"></select>
    </div>
    <textarea id="chatInput" rows="2" placeholder="输入消息..." style="width:100%; margin-top:6px; resize:vertical;">你好！</textarea>
    <div class="chat-output" id="chatOutput">等待测试...</div>
  </div>
</div>

<script>
const BASE = '';
const TOKEN = 'sk-local-apirelay-2026';
const H = { 'Authorization': 'Bearer ' + TOKEN, 'Content-Type': 'application/json' };
let allModels = [];
let dashscopeModels = [];

async function load() {
  try {
    const r = await fetch('/stats', { headers: H });
    const d = await r.json();
    document.getElementById('uptime').textContent = '运行 ' + d.uptime;
    document.getElementById('m_req').textContent = d.stats.total_requests;
    document.getElementById('m_tok').textContent = (d.stats.total_tokens/1000).toFixed(1)+'K';
    document.getElementById('m_err').textContent = d.stats.errors;
    document.getElementById('m_pro').textContent = d.providers.length;
    document.getElementById('providers_list').textContent = d.providers.join(' · ');

    allModels = d.models;
    renderModels(d.models);
    renderChatSelect(d.models);
  } catch(e) {
    document.getElementById('model_list').innerHTML = '<span class="error">连接失败</span>';
  }
}

function renderModels(models) {
  let html = '';
  models.forEach(m => {
    html += `<div class="model-row">
      <span>${m.id} ${m._wildcard ? '<span class="wildcard-tag">🌐 通配</span>' : ''}</span>
      ${m._wildcard
        ? '<span style="font-size:0.7rem;color:var(--blue)">🌐 通配</span>'
        : `<span class="toggle ${m.enabled?'on':'off'}">${m.enabled?'启用':'停用'}</span>`
      }
    </div>`;
  });
  document.getElementById('model_list').innerHTML = html;
}

function renderChatSelect(models) {
  const sel = document.getElementById('chatModel');
  const prev = sel.value;
  sel.innerHTML = '<option value="">选择模型...</option>';
  models.forEach(m => {
    sel.innerHTML += `<option value="${m.id}">${m.id}</option>`;
  });
  if (prev) sel.value = prev;
  onModelChange();
}

function onModelChange() {
  const sel = document.getElementById('chatModel');
  const ws = document.getElementById('wildcardSub');
  if (sel.value === 'qwen/*') {
    ws.style.display = 'block';
    if (dashscopeModels.length === 0) loadDashscopeModels();
    renderDashscopeSelect();
  } else {
    ws.style.display = 'none';
  }
}

async function loadDashscopeModels() {
  try {
    const r = await fetch('/v1/models/dashscope', { headers: H });
    dashscopeModels = await r.json();
  } catch(e) {}
}

function renderDashscopeSelect() {
  const sel = document.getElementById('dashscopeModel');
  const catOrder = ['🆕 最新旗舰','⭐ Qwen3.5','🤔 深度推理','💻 代码编程','📐 数学推理','🧠 Qwen3','🔍 DeepSeek','🌙 Kimi','🔥 智谱GLM','🎭 MiniMax','📦 经典系列','📦 其他'];
  const sorted = [...dashscopeModels].sort((a,b) => {
    const ca=catOrder.indexOf(a._cat), cb=catOrder.indexOf(b._cat);
    return (ca==-1?99:ca)-(cb==-1?99:cb) || a.id.localeCompare(b.id);
  });
  let html = '', lastCat = '';
  sorted.forEach(m => {
    if (m._cat !== lastCat) {
      if (lastCat) html += '</optgroup>';
      html += `<optgroup label="${m._cat}">`;
      lastCat = m._cat;
    }
    html += `<option value="${m.id}">${m.id}</option>`;
  });
  if (lastCat) html += '</optgroup>';
  sel.innerHTML = html;
}

async function sendChat() {
  const sel = document.getElementById('chatModel');
  let modelId = sel.value;
  if (modelId === 'qwen/*') {
    modelId = document.getElementById('dashscopeModel').value;
  }
  if (!modelId) return;

  const input = document.getElementById('chatInput').value.trim();
  if (!input) return;

  const btn = document.getElementById('sendBtn');
  const out = document.getElementById('chatOutput');
  btn.disabled = true;
  out.textContent = '请求中...';

  try {
    const r = await fetch('/v1/chat/completions', {
      method: 'POST', headers: H,
      body: JSON.stringify({
        model: modelId,
        messages: [{role:'user', content: input}],
        max_tokens: 200
      })
    });
    const d = await r.json();
    if (d.choices && d.choices[0]) {
